<?php
declare(strict_types=1);
return static function (PDO $pdo): void {
$pdo->exec("CREATE TABLE course_offerings (id INTEGER PRIMARY KEY AUTOINCREMENT,course_id INTEGER NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('self_paced','live_online','in_person')),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price_ugx INTEGER NOT NULL DEFAULT 0 CHECK(price_ugx>=0),capacity INTEGER,is_published INTEGER NOT NULL DEFAULT 0 CHECK(is_published IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(course_id) REFERENCES cms_courses(id) ON DELETE CASCADE)");
$pdo->exec("CREATE INDEX idx_course_offerings_course ON course_offerings(course_id,is_published,mode)");
$pdo->exec("CREATE TABLE course_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,offering_id INTEGER NOT NULL,title TEXT NOT NULL,agenda TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL CHECK(provider IN('zoom','google_meet','in_person','none')),provider_meeting_id TEXT NOT NULL DEFAULT '',join_url TEXT NOT NULL DEFAULT '',host_url TEXT NOT NULL DEFAULT '',venue_name TEXT NOT NULL DEFAULT '',venue_address TEXT NOT NULL DEFAULT '',venue_notes TEXT NOT NULL DEFAULT '',starts_at_utc TEXT NOT NULL,ends_at_utc TEXT NOT NULL,timezone TEXT NOT NULL,capacity INTEGER,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','scheduled','rescheduled','cancelled','completed','archived')),created_by INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(offering_id) REFERENCES course_offerings(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id))");
$pdo->exec("CREATE INDEX idx_course_sessions_schedule ON course_sessions(status,starts_at_utc)");
$pdo->exec("CREATE TABLE session_enrolments (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,user_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed' CHECK(status IN('confirmed','cancelled','waitlisted')),booked_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(session_id,user_id),FOREIGN KEY(session_id) REFERENCES course_sessions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)");
$pdo->exec("CREATE INDEX idx_session_enrolments_user ON session_enrolments(user_id,status,session_id)");
$pdo->exec("CREATE TABLE session_attendance (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,user_id INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('present','late','absent','excused','pending')),recorded_by INTEGER NOT NULL,reason TEXT NOT NULL DEFAULT '',recorded_at TEXT NOT NULL,UNIQUE(session_id,user_id),FOREIGN KEY(session_id) REFERENCES course_sessions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(recorded_by) REFERENCES users(id))");
$pdo->exec("CREATE TABLE meeting_audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,actor_user_id INTEGER NOT NULL,event_type TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,FOREIGN KEY(session_id) REFERENCES course_sessions(id) ON DELETE CASCADE,FOREIGN KEY(actor_user_id) REFERENCES users(id))");
$pdo->exec("CREATE TABLE meeting_ai_usage (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,session_id INTEGER,model TEXT NOT NULL,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,latency_ms INTEGER NOT NULL DEFAULT 0,outcome TEXT NOT NULL,request_id TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(session_id) REFERENCES course_sessions(id) ON DELETE SET NULL)");
$pdo->exec("CREATE INDEX idx_meeting_ai_usage_user_date ON meeting_ai_usage(user_id,created_at)");
};
